package com.tfadrytracker;

/** Pure, persisted state. A late reward recomputes the current raid from its saved baseline. */
final class DryStreakState
{
	static final int SCHEMA = 1;
	int schema = SCHEMA;
	int personal;
	int team;
	int lastKc;
	int beforePersonal;
	int beforeTeam;
	Outcome outcome = Outcome.NONE;
	boolean canUndo;
	boolean rewardsOpen;
	String lastItem;
	String lastRecipient;
	String beforeLastItem;
	String beforeLastRecipient;

	enum Outcome { NONE, TEAMMATE, SELF }

	boolean complete(int kc)
	{
		if (kc <= lastKc || kc <= 0)
		{
			return false;
		}
		beforePersonal = personal;
		beforeTeam = team;
		beforeLastItem = lastItem;
		beforeLastRecipient = lastRecipient;
		lastKc = kc;
		outcome = Outcome.NONE;
		canUndo = true;
		rewardsOpen = true;
		apply();
		return true;
	}

	boolean observe(Outcome next)
	{
		if (!rewardsOpen || !canUndo || next == null || next.ordinal() <= outcome.ordinal())
		{
			return false;
		}
		outcome = next;
		apply();
		return true;
	}

	boolean closeRewards()
	{
		boolean changed = rewardsOpen;
		rewardsOpen = false;
		return changed;
	}

	boolean recordItem(String item, String recipient, boolean yours)
	{
		if (!rewardsOpen || !canUndo || item == null || recipient == null)
		{
			return false;
		}
		boolean changed = observe(yours ? Outcome.SELF : Outcome.TEAMMATE);
		if (!item.equals(lastItem) || !recipient.equals(lastRecipient))
		{
			lastItem = item;
			lastRecipient = recipient;
			changed = true;
		}
		return changed;
	}

	boolean undo()
	{
		if (!canUndo)
		{
			return false;
		}
		personal = beforePersonal;
		team = beforeTeam;
		lastItem = beforeLastItem;
		lastRecipient = beforeLastRecipient;
		canUndo = false;
		rewardsOpen = false;
		return true;
	}

	boolean isValid()
	{
		return schema == SCHEMA && personal >= 0 && team >= 0 && lastKc >= 0
			&& beforePersonal >= 0 && beforeTeam >= 0 && outcome != null
			&& (!canUndo || lastKc > 0) && (!rewardsOpen || canUndo);
	}

	private void apply()
	{
		personal = outcome == Outcome.SELF ? 0 : increment(beforePersonal);
		team = outcome == Outcome.NONE ? increment(beforeTeam) : 0;
	}

	private static int increment(int n)
	{
		return n == Integer.MAX_VALUE ? n : n + 1;
	}
}

package com.tfadrytracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(TfaDryTrackerConfig.GROUP)
public interface TfaDryTrackerConfig extends Config
{
	String GROUP = "tfadrytracker";

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show overlay",
		description = "Display your personal and team purple dry streaks on the game screen.",
		position = 0
	)
	default boolean showOverlay()
	{
		return true;
	}
}

package com.tfadrytracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.FontMetrics;
import java.util.function.IntSupplier;
import java.util.function.Supplier;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public final class TfaDryTrackerOverlay extends OverlayPanel
{
	private static final Color PURPLE = new Color(194, 155, 255);
	private final Client client;
	private final TfaDryTrackerConfig config;
	private final Supplier<String> account;
	private final IntSupplier personal;
	private final IntSupplier team;
	private final Supplier<String> lastItem;
	private final Supplier<String> lastRecipient;

	public TfaDryTrackerOverlay(Client client, TfaDryTrackerConfig config, Supplier<String> account,
		IntSupplier personal, IntSupplier team)
	{
		this(client, config, account, personal, team, () -> null, () -> null);
	}

	public TfaDryTrackerOverlay(Client client, TfaDryTrackerConfig config, Supplier<String> account,
		IntSupplier personal, IntSupplier team, Supplier<String> lastItem, Supplier<String> lastRecipient)
	{
		this.client = client;
		this.config = config;
		this.account = account;
		this.personal = personal;
		this.team = team;
		this.lastItem = lastItem;
		this.lastRecipient = lastRecipient;
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(OverlayPriority.LOW);
		panelComponent.setPreferredSize(new Dimension(175, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		String currentAccount = account.get();
		if (!config.showOverlay() || client.getGameState() != GameState.LOGGED_IN
			|| currentAccount == null || currentAccount.isEmpty())
		{
			return null;
		}
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("TFA Dry tracker").color(PURPLE).build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Personal dry").right(Integer.toString(personal.getAsInt())).build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Team dry").right(Integer.toString(team.getAsInt())).build());
		String item = lastItem.get();
		if (item == null || item.isEmpty())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Last purple").right("None yet").build());
		}
		else
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Last purple").leftColor(PURPLE).build());
			addWrappedText(graphics.getFontMetrics(), item);
			String recipient = lastRecipient.get();
			if (recipient != null && !recipient.isEmpty())
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left("By").right(recipient).build());
			}
		}
		return super.render(graphics);
	}

	private void addWrappedText(FontMetrics metrics, String text)
	{
		StringBuilder line = new StringBuilder();
		for (String word : text.split("\\s+"))
		{
			String candidate = line.length() == 0 ? word : line + " " + word;
			if (line.length() > 0 && metrics.stringWidth(candidate) > 160)
			{
				panelComponent.getChildren().add(LineComponent.builder().left(line.toString()).build());
				line.setLength(0);
			}
			if (line.length() > 0)
			{
				line.append(' ');
			}
			line.append(word);
		}
		if (line.length() > 0)
		{
			panelComponent.getChildren().add(LineComponent.builder().left(line.toString()).build());
		}
	}
}

package com.tfadrytracker;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.PluginPanel;

/** The sidebar always shows the current RuneScape account's saved counters. */
public final class TfaDryTrackerPanel extends PluginPanel
{
	private static final Color BACKGROUND = new Color(30, 30, 34);
	private static final Color CARD = new Color(43, 43, 49);
	private static final Color PURPLE = new Color(194, 155, 255);
	private static final Color MUTED = new Color(175, 175, 185);
	private static final Color TEXT = new Color(235, 235, 240);

	private final JLabel accountLabel = new JLabel("Log in to load your counters");
	private final JLabel personalValue = new JLabel("0");
	private final JLabel teamValue = new JLabel("0");
	private final JLabel lastItemLabel = new JLabel("None recorded yet");
	private final JLabel lastRecipientLabel = new JLabel(" ");
	private final JLabel statusLabel = new JLabel();
	private final JButton undoButton = new JButton("Undo last raid");

	public TfaDryTrackerPanel(Runnable undo)
	{
		setLayout(new BorderLayout());
		setBackground(BACKGROUND);
		setBorder(new EmptyBorder(16, 12, 16, 12));

		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(BACKGROUND);

		JLabel title = new JLabel("TFA Dry tracker");
		title.setForeground(PURPLE);
		title.setFont(title.getFont().deriveFont(Font.BOLD, 18f));
		addAligned(content, title);
		content.add(Box.createVerticalStrut(5));
		accountLabel.setForeground(MUTED);
		accountLabel.setFont(accountLabel.getFont().deriveFont(11f));
		addAligned(content, accountLabel);
		content.add(Box.createVerticalStrut(18));
		addAligned(content, counterCard("PERSONAL DRY", "Raids since your purple", personalValue));
		content.add(Box.createVerticalStrut(10));
		addAligned(content, counterCard("TEAM DRY", "Raids since anyone's purple", teamValue));
		content.add(Box.createVerticalStrut(10));
		addAligned(content, lastPurpleCard());
		content.add(Box.createVerticalStrut(16));

		statusLabel.setForeground(TEXT);
		statusLabel.setFont(statusLabel.getFont().deriveFont(12f));
		addAligned(content, statusLabel);
		content.add(Box.createVerticalStrut(14));

		JLabel rules = new JLabel("<html><div style='width:183px'>"
			+ "Your purple resets both counters.<br>"
			+ "A teammate's purple resets team only.<br><br>"
			+ "Solo raids count toward both."
			+ "</div></html>");
		rules.setForeground(MUTED);
		rules.setFont(rules.getFont().deriveFont(11f));
		addAligned(content, rules);
		content.add(Box.createVerticalStrut(18));

		undoButton.setEnabled(false);
		undoButton.setFocusable(false);
		undoButton.setToolTipText("Restore the counters from before the most recently recorded raid.");
		undoButton.addActionListener(event -> undo.run());
		addAligned(content, undoButton);
		add(content, BorderLayout.NORTH);
		update(null, 0, 0, "Waiting for a completed raid.", false);
	}

	private static JPanel counterCard(String title, String caption, JLabel value)
	{
		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(CARD);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(new Color(59, 54, 68)), new EmptyBorder(10, 12, 10, 12)));
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, 110));

		JLabel heading = new JLabel(title);
		heading.setFont(heading.getFont().deriveFont(Font.BOLD, 11f));
		heading.setForeground(PURPLE);
		addAligned(card, heading);
		card.add(Box.createVerticalStrut(3));
		value.setFont(value.getFont().deriveFont(Font.BOLD, 32f));
		value.setForeground(TEXT);
		addAligned(card, value);
		JLabel description = new JLabel(caption);
		description.setForeground(MUTED);
		description.setFont(description.getFont().deriveFont(11f));
		addAligned(card, description);
		return card;
	}

	private static void addAligned(JPanel panel, javax.swing.JComponent component)
	{
		component.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.add(component);
	}

	private JPanel lastPurpleCard()
	{
		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(CARD);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(new Color(59, 54, 68)), new EmptyBorder(10, 12, 10, 12)));
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, 140));
		JLabel heading = new JLabel("LAST PURPLE");
		heading.setForeground(PURPLE);
		heading.setFont(heading.getFont().deriveFont(Font.BOLD, 11f));
		addAligned(card, heading);
		card.add(Box.createVerticalStrut(7));
		lastItemLabel.setForeground(TEXT);
		lastItemLabel.setFont(lastItemLabel.getFont().deriveFont(Font.BOLD, 14f));
		addAligned(card, lastItemLabel);
		card.add(Box.createVerticalStrut(4));
		lastRecipientLabel.setForeground(MUTED);
		lastRecipientLabel.setFont(lastRecipientLabel.getFont().deriveFont(11f));
		addAligned(card, lastRecipientLabel);
		return card;
	}

	/** Safe to call from the client thread. Swing mutations are marshalled to the EDT. */
	public void update(String account, int personal, int team, String status, boolean canUndo)
	{
		update(account, personal, team, status, canUndo, null, null);
	}

	/** Refresh counters and the last observed purple item and its recipient. */
	public void update(String account, int personal, int team, String status, boolean canUndo,
		String lastItem, String lastRecipient)
	{
		Runnable updateLabels = () ->
		{
			accountLabel.setText(account == null || account.isEmpty()
				? "Log in to load your counters" : "Account: " + account);
			personalValue.setText(Integer.toString(personal));
			teamValue.setText(Integer.toString(team));
			boolean hasItem = lastItem != null && !lastItem.isEmpty();
			lastItemLabel.setText("<html><div style='width:160px'>"
				+ escape(hasItem ? lastItem : "None recorded yet") + "</div></html>");
			lastRecipientLabel.setText(lastRecipient == null || lastRecipient.isEmpty()
				? " " : "Received by " + lastRecipient);
			statusLabel.setText("<html><div style='width:183px'>" + escape(status) + "</div></html>");
			undoButton.setEnabled(canUndo);
			revalidate();
			repaint();
		};
		if (SwingUtilities.isEventDispatchThread())
		{
			updateLabels.run();
		}
		else
		{
			SwingUtilities.invokeLater(updateLabels);
		}
	}

	private static String escape(String text)
	{
		return text == null ? "" : text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.tfadrytracker;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "TFA Dry tracker",
	description = "Personal and team purple dry streaks for The Fractured Archive",
	tags = {"tfa", "fractured", "archive", "dry", "purple", "raid"}
)
public final class TfaDryTrackerPlugin extends Plugin
{
	private static final Logger LOG = LoggerFactory.getLogger(TfaDryTrackerPlugin.class);
	private static final String DATA_KEY = "stateV1";
	private static final int LOOT_REGION = 16474;
	private static final int FIRST_ROOM_REGION = 16471;
	private static final int FINAL_ROOM_REGION = 16472;

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ConfigManager configManager;
	@Inject private ClientToolbar toolbar;
	@Inject private OverlayManager overlayManager;
	@Inject private TfaDryTrackerConfig config;
	@Inject private Gson gson;

	private DryStreakState state = new DryStreakState();
	private String profileKey;
	private String account;
	private String status = "Log in to start tracking.";
	private TfaDryTrackerPanel panel;
	private TfaDryTrackerOverlay overlay;
	private NavigationButton navigation;
	private int lootTicks;
	private boolean uniqueSeen;
	private final Set<String> party = new HashSet<>();

	@Provides
	TfaDryTrackerConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(TfaDryTrackerConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new TfaDryTrackerPanel(() -> clientThread.invokeLater(this::undo));
		navigation = NavigationButton.builder().tooltip("TFA Dry tracker").icon(icon())
			.priority(7).panel(panel).build();
		toolbar.addNavigation(navigation);
		overlay = new TfaDryTrackerOverlay(client, config, () -> account, () -> state.personal,
			() -> state.team, () -> state.lastItem, () -> state.lastRecipient);
		overlayManager.add(overlay);
		clientThread.invokeLater(() -> { ensureProfile(); refresh(); });
	}

	@Override
	protected void shutDown()
	{
		if (overlay != null) { overlayManager.remove(overlay); }
		if (navigation != null) { toolbar.removeNavigation(navigation); }
		clearSession();
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		clearSession();
		clientThread.invokeLater(() -> { ensureProfile(); refresh(); });
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			clearSession();
			refresh();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		// Public, clan, and private chat can never manufacture a completion.
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}
		int kc = TfaSignals.completedKc(event.getMessage());
		if (kc > 0 && ensureProfile() && !isSpectator() && state.complete(kc))
		{
			resetChestObservations();
			party.clear();
			captureParty();
			status = "KC " + kc + " counted. Awaiting the reward vault.";
			save();
		}
		else if (state.rewardsOpen && ensureProfile() && region() == LOOT_REGION && !isSpectator())
		{
			captureParty();
			TfaSignals.PurpleAnnouncement drop = TfaSignals.purpleAnnouncement(event.getMessage(), party);
			if (drop != null && state.recordItem(drop.item, drop.recipient,
				drop.recipient.equalsIgnoreCase(account)))
			{
				status = drop.recipient + " received " + drop.item + ".";
				save();
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!ensureProfile()) { return; }
		int region = region();
		if (region == FIRST_ROOM_REGION) { party.clear(); }
		if (region == LOOT_REGION || region == FIRST_ROOM_REGION || region == FINAL_ROOM_REGION)
		{
			captureParty();
		}
		if (region == FIRST_ROOM_REGION && state.closeRewards())
		{
			resetChestObservations();
			status = "New raid in progress. Waiting for completion.";
			save();
		}
		if (region != LOOT_REGION || isSpectator() || !state.rewardsOpen)
		{
			if (lootTicks != 0) { resetChestObservations(); }
			return;
		}
		lootTicks++;
		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			NPCComposition composition = npc.getTransformedComposition();
			int id = composition == null ? npc.getId() : composition.getId();
			uniqueSeen |= TfaLootSignals.isUniqueChest(id);
		}
		DryStreakState.Outcome outcome = TfaLootSignals.chestOutcome(uniqueSeen);
		if (state.observe(outcome))
		{
			status = "Purple detected. Team streak reset. Waiting for recipient and item.";
			save();
		}
		else if (!uniqueSeen && lootTicks == 4)
		{
			status = "KC " + state.lastKc + " recorded. No purple detected.";
			refresh();
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.TFA_CHESTS)
		{
			clientThread.invokeLater(this::readPersonalReward);
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.TFA_CHESTS
			&& client.getWidget(InterfaceID.TfaChests.UNIVERSE) != null)
		{
			readPersonalReward();
		}
	}

	private void readPersonalReward()
	{
		if (!ensureProfile() || !state.rewardsOpen || isSpectator()) { return; }
		ItemContainer container = client.getItemContainer(InventoryID.TFA_CHESTS);
		if (container == null) { return; }
		for (Item item : container.getItems())
		{
			if (item.getQuantity() > 0 && TfaLootSignals.isPurpleItem(item.getId()))
			{
				String name = client.getItemDefinition(item.getId()).getName();
				if (state.recordItem(name, account, true))
				{
					status = "Your purple: " + name + ". Both streaks reset.";
					save();
				}
			}
		}
	}

	private boolean ensureProfile()
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
		{
			return false;
		}
		String key = configManager.getRSProfileKey();
		if (key == null) { return false; }
		if (!key.equals(profileKey))
		{
			profileKey = key;
			account = client.getLocalPlayer().getName();
			state = new DryStreakState();
			String json = configManager.getRSProfileConfiguration(TfaDryTrackerConfig.GROUP, DATA_KEY);
			try
			{
				DryStreakState restored = gson.fromJson(json, DryStreakState.class);
				if (restored != null)
				{
					if (!restored.isValid()) { throw new IllegalArgumentException("Invalid saved streak state"); }
					state = restored;
				}
			}
			catch (RuntimeException exception)
			{
				LOG.warn("Unable to read TFA dry tracker state; preserving the original under stateV1Backup", exception);
				configManager.setRSProfileConfiguration(TfaDryTrackerConfig.GROUP, "stateV1Backup", json);
			}
			resetChestObservations();
			status = state.lastKc == 0 ? "Ready. Both counters start at zero."
				: "Saved counters loaded. Last recorded KC: " + state.lastKc + ".";
			refresh();
		}
		return true;
	}

	private void undo()
	{
		if (ensureProfile() && state.undo())
		{
			status = "Last raid undone. Its KC will not be counted again.";
			save();
		}
	}

	private void save()
	{
		// Profile must still be the one to which these in-memory counters belong.
		if (profileKey != null && profileKey.equals(configManager.getRSProfileKey()))
		{
			configManager.setRSProfileConfiguration(TfaDryTrackerConfig.GROUP, DATA_KEY, gson.toJson(state));
		}
		refresh();
	}

	private void refresh()
	{
		if (panel != null)
		{
			panel.update(account, state.personal, state.team, status, state.canUndo,
				state.lastItem, state.lastRecipient);
		}
	}

	private boolean isSpectator()
	{
		return client.getVarbitValue(VarbitID.TFA_CLIENT_SPECTATE_MODE) >= 2;
	}

	private int region()
	{
		return client.getLocalPlayer() == null ? -1 : WorldPoint.fromLocalInstance(client,
			client.getLocalPlayer().getLocalLocation()).getRegionID();
	}

	private void resetChestObservations()
	{
		lootTicks = 0;
		uniqueSeen = false;
	}

	private void captureParty()
	{
		if (account != null) { party.add(account); }
		for (int i = 0; i < 8; i++)
		{
			String name = client.getVarcStrValue(VarClientID.TFA_CLIENT_NAME0 + i);
			if (name != null && !name.trim().isEmpty())
			{
				party.add(name.replace('\u00a0', ' ').trim());
			}
		}
	}

	private void clearSession()
	{
		profileKey = null;
		account = null;
		state = new DryStreakState();
		party.clear();
		status = "Log in to load your counters.";
		resetChestObservations();
	}

